Record Stock Event.code:
// Record a stock movement (receipt, issue or adjustment) using codes, not UUIDs.
post('/public/stockEvents', {
  // Facility code where the movement happened.
  facility: $.data.facilityCode,
  // Program code, e.g. the EPI or family planning program.
  program: $.data.programCode,
  documentNumber: $.data.waybillNumber,
  signature: 'Store Manager',
  items: [
    {
      // Orderable (product) code.
      orderable: $.data.productCode,
      lot: $.data.lotCode,
      // Quantity moved; must not be negative.
      quantity: $.data.quantity,
      // Stock movement reason code.
      reason: $.data.reasonCode,
      occurredDate: $.data.receivedDate, // e.g. '2026-10-15'
    },
  ],
});

Initiate Requisition.code:
// Initiate a requisition (query parameters only, no body).
request(
  // 1) HTTP method.
  'POST',
  // 2) Path relative to the OpenLMIS API.
  '/requisitions/initiate',
  // 3) No body.
  null,
  // 4) Query parameters.
  {
    query: {
      facility: $.data.facilityId, // facility UUID
      program: $.data.programId, // program UUID
      suggestedPeriod: $.data.periodId, // processing period UUID
      emergency: false,
    },
  }
);

Submit Requisition.code:
// Submit an initiated requisition for approval.
post(
  // 1) Requisition UUID in the path.
  `/requisitions/${$.data.requisitionId}/submit`,
  // 2) No body needed.
  {}
);

Approve Requisition.code:
// Approve a requisition by id.
post(
  // 1) Requisition UUID in the path.
  `/requisitions/${$.data.requisitionId}/approve`,
  // 2) No body needed.
  {}
);

Create Facility.code:
// Create a new facility.
post('/facilities', {
  code: $.data.facilityCode, // e.g. 'HC-0421'
  name: $.data.facilityName, // e.g. 'Lilongwe District Health Centre'
  // Geographic zone and facility type reference existing records by id.
  geographicZone: { id: $.data.geographicZoneId },
  type: { id: $.data.facilityTypeId },
  active: true,
  enabled: true,
  goLiveDate: '2026-11-01',
});

Get Stock On Hand.code:
// Get stock on hand for every product at a facility under one program.
get('/v2/stockCardSummaries', {
  query: {
    facilityId: $.data.facilityId, // facility UUID (required)
    programId: $.data.programId, // program UUID (required)
    nonEmptyOnly: true, // skip products with zero stock
    size: 100,
  },
});

Search Requisitions.code:
// Find requisitions for a facility and program.
get('/requisitions/search', {
  query: {
    facility: $.data.facilityId,
    program: $.data.programId,
    requisitionStatus: 'APPROVED', // e.g. INITIATED, SUBMITTED, AUTHORIZED, APPROVED
    modifiedDateFrom: '2026-10-01',
    size: 50,
  },
});

List Facilities.code:
// List facilities in a geographic zone.
get('/facilities', {
  query: {
    zoneId: $.data.districtZoneId, // geographic zone UUID
    recurse: true, // include facilities in child zones
    page: 0,
    size: 100,
  },
});

List Products.code:
// Look up orderable products for a program.
get('/orderables', {
  query: {
    program: $.data.programCode, // program code
    name: 'Amoxicillin', // partial name match
    size: 50,
  },
});

List Orders.code:
// List orders a warehouse needs to ship.
get('/orders', {
  query: {
    supplyingFacilityId: $.data.warehouseId, // supplying facility UUID
    programId: $.data.programId,
    status: 'ORDERED', // e.g. ORDERED, SHIPPED, RECEIVED
    size: 50,
  },
});

List Proofs Of Delivery.code:
// Get proofs of delivery recorded against an order.
get('/proofsOfDelivery', {
  query: {
    orderId: $.data.orderId,
  },
});
